# Confirming the set G = {11a + 20b | a, b >= 0} for small values
limit = 150
G = set()
for a in range(limit // 11 + 1):
    for b in range(limit // 20 + 1):
        s = 11 * a + 20 * b
        if s <= limit:
            G.add(s)

print("Generated set G up to 150:", sorted(list(G)))
